import{_ as p,a0 as i,w as s,s as a,ao as l,I as r,x as o,a1 as e,A as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const c=JSON.parse('{"title":"每日Ubuntu小技巧——了解Root帐号 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧——了解Root帐号 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧——了解Root帐号 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧——了解Root帐号 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Daily Ubuntu Tips–Knowing About The Root Account","title":"每日Ubuntu小技巧——了解Root帐号","tag":"201310","desc":""},"relativePath":"201310/Daily Ubuntu Tips–Knowing About The Root Account.md","filePath":"[post].md"}'),d={name:"201310/Daily Ubuntu Tips–Knowing About The Root Account.md"};function g(b,t,T,m,f,w){const n=i("Link");return s(),a("div",null,[t[11]||(t[11]=l(`<h1 id="每日ubuntu小技巧——了解root帐号" tabindex="-1">每日Ubuntu小技巧——了解Root帐号 <a class="header-anchor" href="#每日ubuntu小技巧——了解root帐号" aria-label="Permalink to “每日Ubuntu小技巧——了解Root帐号”">​</a></h1><p>对于想了解Root帐号的Ubuntu新手，这里有一个简短的文章会让你对root账号和如何使用及为什么使用root账号有些清楚的认识。如你所见，每个版本的Ubuntu都会带一个root账号。</p><p>root账号也被称作管理员账号。你可以将root账号看作是有着同上帝一样的权力的账号。它可以删除任何文件，任何目录并对系统做出任何修改。root账号的权限是无限制的。</p><p>由于root账号过于强大，系统会自动地产生一个密码串，该密码串在系统上不可能通过加密来匹配到，如此一来用户就不能使用root帐号登入系统了。相对直接用root帐号登录，Ubuntu更支持用户使用sudo命令。</p><p>sudo命令可以使已获得授权的用户在不知道root帐号的密码也不使用root帐号的情况下，通过使用自己的密码暂时提升自己的权限。</p><p>如果你因为一些其它原因仍然想要使用root帐号并用它登录系统，很简单，给它设置一个密码就可以了。这样就可以使能root帐号了。</p><pre><code>sudo passwd
</code></pre><p>上面的命令可以激活root帐号，但是想要用root帐号登录系统，你还必须打开被Ubuntu禁用的手动登录功能。手动登录功能允许用户输入帐号和相应的登录密码而不仅仅是从登录界面选择一个帐号登录。</p><p>要在<strong>Ubuntu 13.10</strong>中打开手动登录选项，你可以运行下面的命令</p><pre><code>sudo gedit /etc/lightdm/lightdm.conf.d/50-unity-greeter.conf
</code></pre><p>然后如图所示添加下面这一行文字</p><pre><code>greeter-show-manual-login=true
</code></pre><p><img src="" alt=""></p><p>保存并重启电脑。</p><p>对于较早版本的Ubuntu，你可以在另外一个位置，即<strong>/etc/lightdm</strong>目录下找到这个配置文件。文件名可能叫<strong>lightdm.conf</strong>。</p><p>修改完后，在登录界面，你就可以输入root帐号和相应的密码然后登录系统了。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/ubuntu-root-logon-1.png" alt=""></p><p>如果你想锁定/禁用root帐号，使用下面的命令</p><pre><code>sudo passwd -l root
</code></pre><p>使用愉快！</p><hr>`,21)),r("p",null,[t[1]||(t[1]=o("via: ",-1)),e(n,{href:"http://www.liberiangeek.net/2013/09/daily-ubuntu-tipsknowing-root-account/"},{default:u(()=>[...t[0]||(t[0]=[o("http://www.liberiangeek.net/2013/09/daily-ubuntu-tipsknowing-root-account/",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=o("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[2]||(t[2]=[o("LCTT",-1)])]),_:1}),t[5]||(t[5]=o(" 原创翻译，",-1)),e(n,{href:"http://linux.cn/"},{default:u(()=>[...t[3]||(t[3]=[o("Linux中国",-1)])]),_:1}),t[6]||(t[6]=o(" 荣誉推出",-1))]),r("p",null,[t[9]||(t[9]=o("译者：",-1)),e(n,{href:"https://github.com/Linchenguang"},{default:u(()=>[...t[7]||(t[7]=[o("Linchenguang",-1)])]),_:1}),t[10]||(t[10]=o(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:u(()=>[...t[8]||(t[8]=[o("wxy",-1)])]),_:1})])])}const h=p(d,[["render",g]]);export{c as __pageData,h as default};
